// spec: specs/catalog.md §16 · кейс .qa/tests/catalog/cat-29-import-sku-check-digit.md
// seed: tests/seed.admin.spec.ts
// #dc1afa (באג, עבר QA 29.10, commits 40416f0 / 01d9e35): контрольная цифра מק"ט в предпросмотре импорта из Excel.
//   «מה רצוי»: מק"ט 8/12/13 цифр с неверной контрольной цифрой отмечен в предпросмотре ТОЙ ЖЕ надписью, что в форме товара
//   («ספרת הביקורת של הברקוד שגויה — בדקו את הספרות»); видно, какие строки неверные; можно исправить или явно подтвердить;
//   без подтверждения ничего не записывается.
//   Реализация: ячейка מק"ט aria-invalid + надпись под строкой; счётчик «ספרת ביקורת שגויה: N»; «ייבוא» → окно
//   «לייבא N מק"טים עם ספרת ביקורת שגויה?» («תיקון המק"טים» / «ייבוא בכל זאת»), для одного — «לייבא מק"ט…» / «תיקון המק"ט».
// Запись: в тестах 16.1–16.4 POST products перехватывается (ответ 201 [], в базу ничего не уходит) или не происходит вовсе;
//   реальная запись — только 16.5: один товар «QA-AUTO-dc1afa-<ts>-real», afterAll удаляет его (H.cleanup). AI не нужен
//   (все колонки распознаются по таблице), но import-map всё равно подменён — настоящий вызов модели невозможен.
// Записан вручную (запасной путь): официальный генератор не умеет перехватывать POST products и подменять import-map.
import { test, expect } from '@playwright/test';
import * as H from '../inventory/_places';
import { mockAi } from '../_ai-mock';
import * as I from './_import';

test.use({ storageState: H.ADMIN });

const C = I.codes();
const P = `QA-AUTO-dc1afa-${C.ts}`;
const HEAD = 'שם מוצר,מחיר,מק"ט';
const csv = (...rows: string[]) => [HEAD, ...rows].join('\n') + '\n';
const created = new Set<string>();
/** Текст окна подтверждения начинается с той же надписи, что в форме товара, и списка кодов. */
const WARN_PREFIX = `${I.WARN}:`;

test.describe('catalog — ייבוא מאקסל: ספרת ביקורת של מק"ט בתצוגה המקדימה (#dc1afa)', () => {
  test.beforeEach(async ({ page }) => { await mockAi(page, 'import-map'); });

  test('שורה עם EAN-13 שגוי מסומנת (aria-invalid + «ספרת הביקורת של הברקוד שגויה — בדקו את הספרות»), מונה 1; תיקון הספרה מסיר את הסימון, קלקול מחזיר; תקין — ייבוא בלי חלון #dc1afa @desktop @catalog @prod-safe', async ({ page }) => {
    const writes = I.watchProductWrites(page);
    await I.openImport(page);
    await I.upload(page, csv(`${P}-one,1,${C.E13bad}`));
    const cell = I.skuCell(page, 1);
    await expect(cell).toHaveValue(C.E13bad);
    await expect(cell).toHaveAttribute('aria-invalid', 'true');
    await expect(I.warnings(page)).toHaveCount(1);
    await expect(I.counter(page, 1)).toBeVisible();

    await cell.fill(C.E13);
    await expect(I.anyCounter(page)).toHaveCount(0);
    await expect(I.warnings(page)).toHaveCount(0);
    await expect(cell).not.toHaveAttribute('aria-invalid', 'true');

    await cell.fill(C.E13bad);
    await expect(I.counter(page, 1)).toBeVisible();
    await expect(I.warnings(page)).toHaveCount(1);

    await cell.fill(C.E13);
    await expect(I.anyCounter(page)).toHaveCount(0);
    expect(writes, 'до «ייבוא» ничего не записано').toEqual([]);

    const posted = await I.fakeProductInsert(page);
    await I.importBtn(page).click();
    await expect.poll(() => posted.length, { message: 'верный מק"ט — POST products без окна' }).toBe(1);
    await expect(page.getByRole('dialog')).toHaveCount(0);
    expect(posted[0].map((p) => p.sku)).toEqual([C.E13]);
  });

  test('אורכים 8 / 12 / 13 נבדקים; תקינים, 5 ספרות, 14 ספרות, ABC123 ומק"ט פנימי — בלי סימון; «ייבוא» → חלון «לייבא 4 מק"טים…», 0 בקשות; «תיקון המק"טים» סוגר בלי כתיבה; המונה מוביל לשורה #dc1afa @desktop @catalog @prod-safe', async ({ page }) => {
    const writes = I.watchProductWrites(page);
    await I.openImport(page);
    const rows: Array<[string, string, boolean]> = [
      ['e8bad', C.E8bad, true], ['upcbad', C.UPCbad, true], ['e13bad', C.E13bad, true], ['e13mid', C.E13mid, true],
      ['e8ok', C.E8, false], ['upcok', C.UPC, false], ['e13ok', C.E13b, false],
      ['short', `1${C.ts.slice(-4)}`, false], ['d14', C.D14, false], ['abc', `ABC123-${C.ts}`, false], ['int', `QA-AUTO-X-${C.ts}`, false],
    ];
    // 12 строк-заполнителей (всего 23 — одна страница предпросмотра из 25), отмеченные строки — после них, ниже экрана: проверка «מעבר לשורה».
    const filler = Array.from({ length: 12 }, (_, i) => [`fill${i + 1}`, `QA-INT-${C.ts}-${i + 1}`, false] as [string, string, boolean]);
    const all = [...rows.slice(4), ...filler, ...rows.slice(0, 4)];
    await I.upload(page, csv(...all.map(([n, sku]) => `${P}-${n},1,${sku}`)));
    await expect(I.nameCell(page, all.length)).toHaveValue(`${P}-${all[all.length - 1][0]}`);

    for (let i = 0; i < all.length; i++) {
      const [n, sku, isBad] = all[i];
      const cell = I.skuCell(page, i + 1);
      await expect(cell, `${n}: значение`).toHaveValue(sku);
      if (isBad) await expect(cell, `${n}: отмечен`).toHaveAttribute('aria-invalid', 'true');
      else await expect(cell, `${n}: не отмечен`).not.toHaveAttribute('aria-invalid', 'true');
    }
    await expect(I.warnings(page)).toHaveCount(4);
    await expect(I.counter(page, 4)).toBeVisible();

    // «ספרת ביקורת שגויה: 4 — מעבר לשורה» → первая отмеченная строка на экране.
    const firstBad = I.skuCell(page, all.length - 3);
    await expect(firstBad).not.toBeInViewport();
    await I.counter(page, 4).click();
    await expect(firstBad).toBeInViewport();

    await page.evaluate(() => window.scrollTo(0, 0));
    await I.importBtn(page).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'לייבא 4 מק"טים עם ספרת ביקורת שגויה?' })).toBeVisible();
    for (const sku of [C.E8bad, C.UPCbad, C.E13bad, C.E13mid]) await expect(dlg).toContainText(sku);
    await expect(dlg).toContainText(WARN_PREFIX);
    await expect(dlg.getByRole('button', { name: 'תיקון המק"טים', exact: true })).toBeVisible();
    await expect(dlg.getByRole('button', { name: 'ייבוא בכל זאת', exact: true })).toBeVisible();
    expect(writes, 'окно открыто — 0 запросов записи').toEqual([]);

    await dlg.getByRole('button', { name: 'תיקון המק"טים', exact: true }).click();
    await expect(dlg).toHaveCount(0);
    await expect(I.counter(page, 4)).toBeVisible();
    expect(writes, '«תיקון המק"טים» — ничего не записано').toEqual([]);
  });

  test('הוצאת שורה מסומנת (סל) מעדכנת מונה וחלון; כשאין שורות מסומנות — «ייבוא» בלי חלון, רק השורה התקינה נשלחת #dc1afa @desktop @catalog @prod-safe', async ({ page }) => {
    const writes = I.watchProductWrites(page);
    await I.openImport(page);
    await I.upload(page, csv(`${P}-r1,1,${C.E8bad}`, `${P}-r2,1,${C.UPCbad}`, `${P}-r3,1,${C.E13bad}`));
    await expect(I.counter(page, 3)).toBeVisible();
    await page.getByRole('button', { name: 'הוצאת שורה 1', exact: true }).click();
    await expect(I.counter(page, 2)).toBeVisible();
    await expect(I.warnings(page)).toHaveCount(2);
    await I.importBtn(page).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'לייבא 2 מק"טים עם ספרת ביקורת שגויה?' })).toBeVisible();
    await expect(dlg).not.toContainText(C.E8bad);
    await dlg.getByRole('button', { name: 'תיקון המק"טים', exact: true }).click();
    await expect(dlg).toHaveCount(0);

    // Файл «неверный + внутренний»: убрать неверный → отметок нет → импорт без вопроса.
    await I.openImport(page);
    await I.upload(page, csv(`${P}-two-bad,1,${C.E13bad}`, `${P}-two-ok,1,QA-INT-${C.ts}-two`));
    await expect(I.counter(page, 1)).toBeVisible();
    await page.getByRole('button', { name: 'הוצאת שורה 1', exact: true }).click();
    await expect(I.anyCounter(page)).toHaveCount(0);
    expect(writes, 'до «ייבוא» ничего не записано').toEqual([]);
    const posted = await I.fakeProductInsert(page);
    await I.importBtn(page).click();
    await expect.poll(() => posted.length, { message: 'POST products без окна' }).toBe(1);
    await expect(page.getByRole('dialog')).toHaveCount(0);
    expect(posted[0].map((p) => p.name)).toEqual([`${P}-two-ok`]);
  });

  test('כפילויות כמו קודם: מק"ט שכבר בקטלוג — «קיים בקטלוג — ידולג»; אותו מק"ט פעמיים בקובץ — «מק"ט כפול בגיליון» #dc1afa @desktop @catalog @prod-safe', async ({ page }) => {
    const writes = I.watchProductWrites(page);
    const [res] = await Promise.all([
      page.waitForResponse((r) => /\/rest\/v1\/products\?select=\*/.test(r.url()), { timeout: 30_000 }),
      I.openImport(page),
    ]);
    const list = (await res.json()) as Array<{ sku: string | null }>;
    const existing = list.map((p) => p.sku ?? '').find((s) => /^\d{13}$/.test(s) && Number(s[12]) === I.checkDigit(s.slice(0, 12)));
    expect(existing, 'в каталоге есть товар с верным EAN-13').toBeTruthy();
    await I.upload(page, csv(`${P}-dup-cat,1,${existing}`, `${P}-dup-f1,1,${C.E13b}`, `${P}-dup-f2,1,${C.E13b}`));
    const status = (n: number) => I.nameCell(page, n).locator('xpath=ancestor::*[.//button[starts-with(@aria-label,"הוצאת שורה")]][1]');
    await expect(status(1)).toContainText('קיים בקטלוג — ידולג');
    await expect(status(3)).toContainText('מק"ט כפול בגיליון');
    await expect(page.getByRole('button', { name: /^ידולגו: 1/ })).toBeVisible();
    await expect(I.anyCounter(page)).toHaveCount(0);
    expect(writes).toEqual([]);
  });

  test.describe('ייבוא אמיתי (QA-AUTO, נמחק ב-afterAll)', () => {
    test.afterAll(async ({ browser }) => {
      test.setTimeout(120_000);
      await H.cleanup(browser, created, new Map());
    });

    test('«ייבוא בכל זאת» כותב את המק"ט כמו שהוא רק אחרי האישור (0 בקשות לפני); בטופס «עריכת מוצר» — אותה הודעה #dc1afa @desktop @catalog @data', async ({ page }) => {
      const name = `${P}-real`;
      const writes = I.watchProductWrites(page);
      await I.openImport(page);
      await I.upload(page, csv(`${name},1,${C.E13bad}`));
      await expect(I.counter(page, 1)).toBeVisible();
      await I.importBtn(page).click();
      const dlg = page.getByRole('dialog');
      await expect(dlg.getByRole('heading', { name: 'לייבא מק"ט עם ספרת ביקורת שגויה?' })).toBeVisible();
      await expect(dlg.getByRole('button', { name: 'תיקון המק"ט', exact: true })).toBeVisible();
      expect(writes, 'до подтверждения — 0 запросов записи').toEqual([]);
      created.add(name);
      const [resp] = await Promise.all([
        page.waitForResponse((r) => r.url().includes('/rest/v1/products') && r.request().method() === 'POST', { timeout: 15_000 }),
        dlg.getByRole('button', { name: 'ייבוא בכל זאת', exact: true }).click(),
      ]);
      expect(resp.status()).toBe(201);
      expect(JSON.parse(resp.request().postData() || '[]')[0]?.sku).toBe(C.E13bad);

      await H.findProduct(page, name);
      await page.getByRole('button', { name, exact: true }).click();
      await expect(page.getByRole('heading', { level: 1, name: 'עריכת מוצר' })).toBeVisible({ timeout: 20_000 });
      await expect(page.getByRole('textbox', { name: /מק"ט/ })).toHaveValue(C.E13bad);
      await expect(page.getByText(I.WARN, { exact: true })).toBeVisible();
    });
  });
});

